import React, {useState} from 'react'

export default function Art({src, pal, key}) {

    const [isShown, setIsShown] = useState(false);
    console.log(isShown);

    return (
        <div>

            <div 
            className={""}
            onMouseEnter={() => setIsShown(true)}
            onMouseLeave={() => setIsShown(false)}
            >

                <div className={`  `}>  
                {pal.map((color, index) => {
                    return (
                        <div key={index} Style={"background-color: " + color} className={"w-6 h-8 mx-2"} ></div>
                    );
                })}
                </div>
                <img key={key} Style={isShown ? "transform: scaleX(12)" : ""} className={` ${ isShown ? "visible mx-24" : "invisible mx-2" } transition-all duration-700 ease-out h-48 w-4`} src={src} ></img>
            </div>
        </div>
    )
}
